def is_3_colorable(n, edges_set):
    # Backtracking to check 3-colorability
    colors = [-1] * n

    def can_color(v, c):
        for i in range(n):
            if (min(v, i), max(v, i)) in edges_set and colors[i] == c:
                return False
        return True

    def solve(v):
        if v == n:
            return True
        for c in range(3):
            if can_color(v, c):
                colors[v] = c
                if solve(v + 1):
                    return True
                colors[v] = -1
        return False

    return solve(0)

